__constant__ int Mx[9];
int h_Mx[9] = { -1, 0, 1,  -2, 0, 2,  -1, 0, 1 };
cudaMemcpyToSymbol(Mx, h_Mx, sizeof(h_Mx));      // pas cudaMemcpy : Mx n'est pas alloué

__global__ void sobelModule(const unsigned char * __restrict__ in,
                            unsigned char *out, int L, int H) {
    int x = threadIdx.x + blockIdx.x * blockDim.x;
    int y = threadIdx.y + blockIdx.y * blockDim.y;
    if (x < 1 || y < 1 || x >= L - 1 || y >= H - 1) return;
    int p00 = in[(y-1)*L + x-1], p01 = in[(y-1)*L + x], p02 = in[(y-1)*L + x+1];
    int p10 = in[ y   *L + x-1],                         p12 = in[ y   *L + x+1];
    int p20 = in[(y+1)*L + x-1], p21 = in[(y+1)*L + x], p22 = in[(y+1)*L + x+1];
    int gx = -p00 + p02 - 2 * p10 + 2 * p12 - p20 + p22;
    int gy = -p00 - 2 * p01 - p02 + p20 + 2 * p21 + p22;
    out[y * L + x] = min((int)sqrtf((float)(gx * gx + gy * gy)), 255);
}
```
La **mémoire constante** (64 Ko, lecture seule, en cache) diffuse un coefficient à tout le warp en une lecture : idéal quand les 32 threads lisent le même. Si les coefficients sont écrits en dur (comme ici), le compilateur les met déjà dans les instructions : la version constante n'est utile que si le masque est un paramètre.
Autres pistes : la tuile en shared memory (fiche suivante), la mémoire **texture** (cache 2D, gestion des bords), plusieurs pixels par thread, |Gx| + |Gy| au lieu de la racine, `sqrtf` et pas `sqrt`.

```
#define TX 32
#define TY 8

__global__ void sobelShared(const unsigned char *in, unsigned char *out, int L, int H) {
    __shared__ unsigned char tuile[TY + 2][TX + 2];

    // 1. chargement coopératif de la tuile et de son halo (bords répliqués)
    for (int j = threadIdx.y; j < TY + 2; j += TY)
        for (int i = threadIdx.x; i < TX + 2; i += TX) {
            int cx = min(max((int)(blockIdx.x * TX) + i - 1, 0), L - 1);
            int cy = min(max((int)(blockIdx.y * TY) + j - 1, 0), H - 1);
            tuile[j][i] = in[cy * L + cx];
        }
    __syncthreads();

    // 2. calcul depuis la shared memory
    int x = blockIdx.x * TX + threadIdx.x;
    int y = blockIdx.y * TY + threadIdx.y;
    if (x < 1 || y < 1 || x >= L - 1 || y >= H - 1) return;   // après la barrière
    int tx = threadIdx.x + 1, ty = threadIdx.y + 1;
    int gx = -     tuile[ty - 1][tx - 1] +     tuile[ty - 1][tx + 1]
             - 2 * tuile[ty    ][tx - 1] + 2 * tuile[ty    ][tx + 1]
             -     tuile[ty + 1][tx - 1] +     tuile[ty + 1][tx + 1];
    out[y * L + x] = min(abs(gx), 255);
}
// lancement : dim3 threads(TX, TY); dim3 blocs((L + TX - 1) / TX, (H + TY - 1) / TY);
```
Chaque pixel de la tuile est lu **une fois** en mémoire globale, puis réutilisé par les threads voisins depuis la shared memory. Les lectures du chargement restent coalescées (les `i` consécutifs lisent des pixels consécutifs).
Le gain dépend de la carte : les GPU récents ont un cache L1 qui absorbe déjà une partie des relectures. C'est justement ce que l'exercice demande : appliquer, chronométrer, comparer.
